import{_ as l,H as A,o as t,c as d,aN as a,q as e,s as o,a as s,l as i,aT as E}from"./chunks/framework.D31DlcCL.js";const _=JSON.parse('{"title":"AI大模型修仙传（五）：Transformer下篇——位置编码与大模型的“奇经八脉”","description":"一文看懂Transformer核心机制！从位置编码到多头注意力，再到前馈神经网络，带你打通AI大模型的任督二脉。","frontmatter":{"title":"AI大模型修仙传（五）：Transformer下篇——位置编码与大模型的“奇经八脉”","date":"2026-04-01T00:00:00.000Z","categories":["AI"],"tags":["Transformer","深度学习","大模型","NLP"],"description":"一文看懂Transformer核心机制！从位置编码到多头注意力，再到前馈神经网络，带你打通AI大模型的任督二脉。"},"headers":[],"relativePath":"posts/ai-series-5-transformer-architecture.md","filePath":"posts/ai-series-5-transformer-architecture.md","lastUpdated":null}'),p={name:"posts/ai-series-5-transformer-architecture.md"};function m(g,r,B,f,u,T){const n=A("Mermaid");return t(),d("div",null,[r[3]||(r[3]=a('<h1 id="ai大模型修仙传-五-transformer下篇——位置编码与大模型的-奇经八脉" tabindex="-1">AI大模型修仙传（五）：Transformer下篇——位置编码与大模型的“奇经八脉” <a class="header-anchor" href="#ai大模型修仙传-五-transformer下篇——位置编码与大模型的-奇经八脉" aria-label="Permalink to &quot;AI大模型修仙传（五）：Transformer下篇——位置编码与大模型的“奇经八脉”&quot;">​</a></h1><blockquote><p><strong>💡 博主导读</strong>：如果说Attention是心脏，那今天讲的这些就是Transformer的骨架。掌握了这些，你就能在面试和技术交流中降维打击对手！</p></blockquote><h1 id="ai大模型修仙传-五-transformer下篇——位置编码与大模型的-奇经八脉-1" tabindex="-1">AI大模型修仙传（五）：Transformer下篇——位置编码与大模型的“奇经八脉” <a class="header-anchor" href="#ai大模型修仙传-五-transformer下篇——位置编码与大模型的-奇经八脉-1" aria-label="Permalink to &quot;AI大模型修仙传（五）：Transformer下篇——位置编码与大模型的“奇经八脉”&quot;">​</a></h1><p>各位道友，欢迎回到我们的《AI大模型修仙传》。</p><p>在上篇中，我们拆解了Transformer的绝对核心机密——<strong>注意力机制（Attention）</strong>，搞懂了Q、K、V这三个相爱相杀的变量是如何让AI学会“抓重点”的。如果你还没看过上篇，强烈建议先去补补课，否则今天的功法容易让你走火入魔。</p><p>今天，我们要补全Transformer的完整拼图。</p><p>你可能会问：既然注意力机制已经这么强了，能看清词与词之间的关系，那直接把它套进模型里不就行了？</p><p>天真了！如果只用纯粹的注意力机制，AI会瞬间变成一个“文盲”。为什么？因为纯粹的注意力机制，是一个<strong>没有时间观念</strong>的法术。</p><p>今天，我们就来打通Transformer的奇经八脉，看看<strong>位置编码（Positional Encoding）</strong>、**多头注意力（Multi-head Attention）<strong>以及</strong>前馈神经网络（Feed Forward）**是如何强强联手，造就今天称霸武林的ChatGPT等大模型的。</p><hr><h2 id="第一式-位置编码-positional-encoding-——给词汇发个gps定位" tabindex="-1">第一式：位置编码（Positional Encoding）——给词汇发个GPS定位 <a class="header-anchor" href="#第一式-位置编码-positional-encoding-——给词汇发个gps定位" aria-label="Permalink to &quot;第一式：位置编码（Positional Encoding）——给词汇发个GPS定位&quot;">​</a></h2>',11)),(t(),e(E,null,{default:o(()=>[i(n,{id:"mermaid-33",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Word%5B%E8%AF%8D%E6%B1%87%3A%20%E5%92%AC%5D%20--%3E%20Embed%5B%E8%AF%8D%E5%90%91%E9%87%8F%20Embedding%5D%0A%20%20%20%20Pos%5B%E4%BD%8D%E7%BD%AE%3A%20%E7%AC%AC2%E5%8F%B7%5D%20--%3E%20PosEmbed%5B%E4%BD%8D%E7%BD%AE%E5%90%91%E9%87%8F%20Positional%20Encoding%5D%0A%20%20%20%20Embed%20--%3E%20Sum((%E7%9B%B8%E5%8A%A0))%0A%20%20%20%20PosEmbed%20--%3E%20Sum%0A%20%20%20%20Sum%20--%3E%20Model%5B%E9%80%81%E5%85%A5Transformer%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20style%20Sum%20fill%3A%23f9f%2Cstroke%3A%23333%0A"})]),fallback:o(()=>[...r[0]||(r[0]=[s(" Loading... ",-1)])]),_:1})),r[4]||(r[4]=a('<p>在人类的语言中，语序就是生命。</p><p>“狗咬人”和“人咬狗”，虽然词汇完全一样，但前者是日常，后者是新闻。</p><p>然而，在我们上篇讲的纯注意力机制眼里，它就像一个超级大锅乱炖。你把“人”、“咬”、“狗”扔进去，它两两计算相关性，但它<strong>根本不知道谁在前面，谁在后面</strong>。在它看来，“狗咬人”和“人咬狗”算出来的结果是一模一样的。</p><p>这怎么行？为了解决这个问题，祖师爷们发明了<strong>位置编码（Positional Encoding）</strong>。</p><p>既然你不知道词的位置，那我就硬塞给你！</p><p>具体怎么做？很简单，给每个词发一个“座位号”。在模型的最开始，我们不仅把词汇转换成向量（词向量），还会额外生成一个同样维度的“位置向量”。然后，把<strong>词向量 + 位置向量</strong>，揉在一起，再送进模型里。</p><p>这时候，原本长得一模一样的两个“咬”字，因为一个坐在第2号位，一个坐在第4号位，加上了不同的位置向量后，在模型眼里就变成了两个完全不同的词。</p><blockquote><p><strong>硬核揭秘：为什么用正弦和余弦函数？</strong></p><p>在原论文中，作者使用了一组极其优美的正弦（Sine）和余弦（Cosine）函数来生成位置向量。为什么要搞这么复杂的三角函数，而不是直接用1、2、3、4？</p><p>想象一下机械手表的表盘：秒针转得飞快，分针转得慢，时针转得最慢。 正弦余弦函数的不同频率，就像表盘上的多根指针。模型通过观察不同维度上“波”的交替频率，不仅能准确定位绝对位置，还能极其方便地计算出<strong>相对位置</strong>。更绝的是，就算测试时遇到比训练时更长的句子，这套像时钟一样循环的三角函数也能从容应对。</p></blockquote><hr><h2 id="第二式-多头注意力-multi-head-attention-——大模型的-多重影分身之术" tabindex="-1">第二式：多头注意力（Multi-Head Attention）——大模型的“多重影分身之术” <a class="header-anchor" href="#第二式-多头注意力-multi-head-attention-——大模型的-多重影分身之术" aria-label="Permalink to &quot;第二式：多头注意力（Multi-Head Attention）——大模型的“多重影分身之术”&quot;">​</a></h2>',10)),(t(),e(E,null,{default:o(()=>[i(n,{id:"mermaid-70",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Input%5B%E8%BE%93%E5%85%A5%E5%90%91%E9%87%8F%5D%20--%3E%20H1%5B%E5%A4%B41%3A%20%E8%AF%AD%E6%B3%95%E8%A7%86%E8%A7%92%5D%0A%20%20%20%20Input%20--%3E%20H2%5B%E5%A4%B42%3A%20%E5%AE%9E%E4%BD%93%E8%A7%86%E8%A7%92%5D%0A%20%20%20%20Input%20--%3E%20H3%5B%E5%A4%B43%3A%20%E6%83%85%E6%84%9F%E8%A7%86%E8%A7%92%5D%0A%20%20%20%20H1%20--%3E%20Concat((%E6%8B%BC%E6%8E%A5%20Concat))%0A%20%20%20%20H2%20--%3E%20Concat%0A%20%20%20%20H3%20--%3E%20Concat%0A%20%20%20%20Concat%20--%3E%20Linear%5B%E7%BA%BF%E6%80%A7%E5%B1%82%E8%9E%8D%E5%90%88%5D%0A%20%20%20%20style%20Concat%20fill%3A%23bbf%2Cstroke%3A%23333%0A"})]),fallback:o(()=>[...r[1]||(r[1]=[s(" Loading... ",-1)])]),_:1})),r[5]||(r[5]=a('<p>有了位置感之后，我们的AI终于能正常读句子了。但是，理解一句话，只用一种视角够吗？</p><p>举个例子：“那个苹果公司新出的苹果，不仅看起来像苹果，吃起来也像苹果。”</p><p>要理解这句话，你需要：</p><ol><li><strong>语法视角</strong>：谁是主语，谁是谓语？</li><li><strong>实体视角</strong>：哪个“苹果”是科技公司，哪个是水果？</li><li><strong>情感视角</strong>：这句话是在夸它还是在讽刺？</li></ol><p>如果只有一个注意力机制（单头），它可能看顾了语法，就顾不上语义，脑子转不过弯。</p><p>于是，Transformer祭出了第二大神技：<strong>多头注意力（Multi-Head Attention）</strong>。</p><p>这就好比火影忍者里的“多重影分身之术”。模型不再只派一个人去算Q、K、V，而是把原来的高维向量<strong>切分成很多份</strong>，派给多个“头（Head）”去分别计算。</p><ul><li>一号头，专门负责找句子里的代词指代（比如“他”指的是谁）。</li><li>二号头，专门负责找动宾搭配（比如“打”配的是“篮球”还是“酱油”）。</li><li>三号头，专门捕捉标点符号带来的语气停顿。</li></ul><p>最后，等所有影分身都收集完情报，再把它们的结果**拼接（Concat）**在一起，经过一个线性层融合。这样一来，模型就获得了一个360度无死角的上帝视角，对文本的理解深度瞬间暴增。</p><p>现在的千亿参数大模型，动辄几十甚至上百个“头”，就是为了能把人类语言里的那些弯弯绕绕，看得清清楚楚、明明白白。</p><hr><h2 id="第三式-前馈神经网络-feed-forward-——提纯灵气的-炼丹炉" tabindex="-1">第三式：前馈神经网络（Feed Forward）——提纯灵气的“炼丹炉” <a class="header-anchor" href="#第三式-前馈神经网络-feed-forward-——提纯灵气的-炼丹炉" aria-label="Permalink to &quot;第三式：前馈神经网络（Feed Forward）——提纯灵气的“炼丹炉”&quot;">​</a></h2><p>有了多头注意力，模型是不是就天下无敌了？</p><p>别急。注意力机制虽然巧妙，但如果你仔细看它的数学公式，你会发现它本质上只是在做<strong>加权求和</strong>。在数学上，这属于“线性操作”。</p><p>如果整个网络全都是线性操作，那不管你叠多少层，最后的效果和只有一层是一样的。这就好比你把一堆食材切碎了混在一起，如果没有“加热”这个发生化学反应的非线性过程，它永远成不了一道菜。</p><p>所以，在每个多头注意力层的后面，都紧紧跟着一个<strong>前馈神经网络（Feed Forward Network, FFN）</strong>。</p><p>这就好比大模型的“炼丹炉”。</p><p>前馈神经网络通常包含两层全连接层，中间夹着一个非线性激活函数（比如ReLU或GELU）。它的操作极其暴力且有效：</p><ol><li><strong>先膨胀</strong>：先把数据的维度放大，通常是放大4倍。这就好比把揉在一团的线索，全部铺开在一个巨大的桌面上。</li><li><strong>做非线性过滤</strong>：通过激活函数，把没用的噪音（负数）全部砍掉，只保留有用的特征。</li><li><strong>再压缩</strong>：把过滤后的高价值信息，重新压缩回原来的维度。</li></ol><p>如果说注意力机制的作用是**“收集情报”<strong>（看看周围其他词和我的关系），那么前馈神经网络的作用就是</strong>“深度思考”**（把收集到的情报进行加工、提纯，转化成更高级的认知）。</p><hr><h2 id="第四式-残差连接与归一化-add-norm-——防止走火入魔的-护体神功" tabindex="-1">第四式：残差连接与归一化（Add &amp; Norm）——防止走火入魔的“护体神功” <a class="header-anchor" href="#第四式-残差连接与归一化-add-norm-——防止走火入魔的-护体神功" aria-label="Permalink to &quot;第四式：残差连接与归一化（Add &amp; Norm）——防止走火入魔的“护体神功”&quot;">​</a></h2><p>讲完了三大核心招式，最后我们还要提一下保障大模型能够修炼到百层、千层境界的护体神功：<strong>Add &amp; Norm</strong>。</p><p>在大模型的修炼过程中，如果层数太深，很容易出现“梯度消失”或者“梯度爆炸”，俗称走火入魔。为了解决这个问题，Transformer在每个注意力层和前馈层周围，都加了两道保险：</p><ol><li><p><strong>残差连接（Add / Residual Connection）</strong>： 在把数据送进子层处理之前，先拉一根线绕过去，把原始数据和处理后的数据加在一起。意思就是：“不管新学到了什么花里胡哨的东西，千万别忘了你原本是谁。”这极大缓解了深层网络遗忘原始信息的问题。</p></li><li><p><strong>层归一化（Layer Normalization）</strong>： 在残差相加之后，对数据进行一次“标准化”洗礼。把那些过大或者过小的数值，强行拉回到一个均值为0、方差为1的标准范围内。这就好比给模型吃了一颗定心丸，保证数据在网络中流转时，始终平稳安定，不会因为某个数值暴走而全盘崩溃。</p></li></ol><hr><h2 id="万法归宗-transformer的完整周天" tabindex="-1">万法归宗：Transformer的完整周天 <a class="header-anchor" href="#万法归宗-transformer的完整周天" aria-label="Permalink to &quot;万法归宗：Transformer的完整周天&quot;">​</a></h2>',27)),(t(),e(E,null,{default:o(()=>[i(n,{id:"mermaid-197",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20In%5B%E8%BE%93%E5%85%A5%E8%AF%8D%E5%90%91%E9%87%8F%20%2B%20%E4%BD%8D%E7%BD%AE%E7%BC%96%E7%A0%81%5D%20--%3E%20MultiHead%5B%E5%A4%9A%E5%A4%B4%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%9C%BA%E5%88%B6%5D%0A%20%20%20%20In%20--%3E%7C%E6%AE%8B%E5%B7%AE%E8%BF%9E%E6%8E%A5%7C%20Add1((Add))%0A%20%20%20%20MultiHead%20--%3E%20Add1%0A%20%20%20%20Add1%20--%3E%20Norm1%5B%E5%B1%82%E5%BD%92%E4%B8%80%E5%8C%96%20LayerNorm%5D%0A%20%20%20%20Norm1%20--%3E%20FFN%5B%E5%89%8D%E9%A6%88%E7%A5%9E%E7%BB%8F%E7%BD%91%E7%BB%9C%20FFN%5D%0A%20%20%20%20Norm1%20--%3E%7C%E6%AE%8B%E5%B7%AE%E8%BF%9E%E6%8E%A5%7C%20Add2((Add))%0A%20%20%20%20FFN%20--%3E%20Add2%0A%20%20%20%20Add2%20--%3E%20Norm2%5B%E5%B1%82%E5%BD%92%E4%B8%80%E5%8C%96%20LayerNorm%5D%0A%20%20%20%20Norm2%20--%3E%20Out%5B%E8%BE%93%E5%87%BA%E6%9B%B4%E9%AB%98%E9%98%B6%E8%AF%AD%E4%B9%89%E5%90%91%E9%87%8F%5D%0A%20%20%20%20style%20Norm1%20fill%3A%23dfd%2Cstroke%3A%23333%0A%20%20%20%20style%20Norm2%20fill%3A%23dfd%2Cstroke%3A%23333%0A"})]),fallback:o(()=>[...r[2]||(r[2]=[s(" Loading... ",-1)])]),_:1})),r[6]||(r[6]=a('<p>现在，让我们把所有的零件组装起来，看看一个完整的Transformer Block（编码器层）长什么样：</p><ol><li>词汇带着<strong>位置编码</strong>，进入大门。</li><li>兵分两路，一路保留原样，另一路进入<strong>多头注意力</strong>，去和句子里的其他词交换情报。</li><li>情报交换完毕后，和原来的自己相加，并进行<strong>层归一化（Add &amp; Norm）</strong>。</li><li>再次兵分两路，一路保留原样，另一路进入**前馈神经网络（FFN）**进行深度思考和提纯。</li><li>思考完毕，再次和原来的自己相加，并进行<strong>层归一化（Add &amp; Norm）</strong>。</li></ol><p>这就是一个完整的小周天循环。</p><p>而在真正的大模型里，这样的Block会重复堆叠几十次甚至上百次！</p><p>每一层，词向量都在不断地观察别人、反思自己、提取更高级的语义。经过几十层的淬炼，最开始那个干巴巴的“词”，就已经变成了一个包含了无尽上下文语义、情感、逻辑的终极形态。</p><p>此时，只要你在最后接一个预测下一个词的输出层，它就能滔滔不绝地写诗、写代码、甚至和你探讨哲学。</p><hr><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>从注意力机制的惊艳登场，到位置编码的精妙补充；从多头注意力的多维视角，到前馈网络的深度炼化。Transformer架构以一种几乎完美的优雅姿态，打破了过去RNN/CNN在自然语言处理上的瓶颈，彻底推开了通用人工智能（AGI）的大门。</p><p>它不再需要像人类那样顺序阅读，而是以上帝视角，在平行的维度中瞬间看透语言的本质。</p><p>读到这里，你已经掌握了当今AI时代最核心的武功秘籍。下次再有人跟你吹嘘什么千亿参数、什么GPT-4，你大可以微微一笑：“不就是一堆Transformer Block堆起来的嘛，核心不过是多头注意力和FFN罢了。”</p><p><strong>如果你觉得这篇“修仙传”让你醍醐灌顶，别忘了分享给你的技术搭子，大家一起打通大模型的任督二脉！我们下期再见！</strong></p>',12))])}const c=l(p,[["render",m]]);export{_ as __pageData,c as default};
